    46→// NewTestEnv creates a new isolated test environment.
    47→// It creates temp directories for the git repo and Claude project files.
    48→// Note: Does NOT change working directory to allow parallel test execution.
    49→// Note: Does NOT use t.Setenv to allow parallel test execution - CLI commands
    50→// receive the env var via cmd.Env instead.
    51→func NewTestEnv(t *testing.T) *TestEnv {
    52→	t.Helper()
    53→
    54→	// Resolve symlinks on macOS where /var -> /private/var
    55→	// This ensures the CLI subprocess and test use consistent paths
    56→	repoDir := t.TempDir()
    57→	if resolved, err := filepath.EvalSymlinks(repoDir); err == nil {
    58→		repoDir = resolved
    59→	}
    60→	claudeProjectDir := t.TempDir()
    61→	if resolved, err := filepath.EvalSymlinks(claudeProjectDir); err == nil {
    62→		claudeProjectDir = resolved
    63→	}
    64→
    65→	env := &TestEnv{
    66→		T:                t,
    67→		RepoDir:          repoDir,
    68→		ClaudeProjectDir: claudeProjectDir,
    69→	}
    70→
    71→	// Note: Don't use t.Setenv here - it's incompatible with t.Parallel()
    72→	// CLI commands receive ENTIRE_TEST_CLAUDE_PROJECT_DIR via cmd.Env instead
    73→
    74→	return env
    75→}
