   132→// RunForAllStrategies runs a test function for each strategy in parallel.
   133→// This reduces boilerplate for tests that need to verify behavior across all strategies.
   134→// Each subtest gets its own TestEnv with a feature branch ready for testing.
   135→func RunForAllStrategies(t *testing.T, testFn func(t *testing.T, env *TestEnv, strategyName string)) {
   136→	t.Helper()
   137→	for _, strat := range AllStrategies() {
   138→		strat := strat // capture for parallel
   139→		t.Run(strat, func(t *testing.T) {
   140→			t.Parallel()
   141→			env := NewFeatureBranchEnv(t, strat)
   142→			testFn(t, env, strat)
   143→		})
   144→	}
   145→}
