   535→// GetRewindPoints returns available rewind points using the CLI.
   536→func (env *TestEnv) GetRewindPoints() []RewindPoint {
   537→	env.T.Helper()
   538→
   539→	// Run rewind --list using the shared binary
   540→	cmd := exec.Command(getTestBinary(), "rewind", "--list")
   541→	cmd.Dir = env.RepoDir
   542→	cmd.Env = append(os.Environ(),
   543→		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
   544→	)
   545→
   546→	output, err := cmd.CombinedOutput()
   547→	if err != nil {
   548→		env.T.Fatalf("rewind --list failed: %v\nOutput: %s", err, output)
   549→	}
   550→
   551→	// Parse JSON output
   552→	var jsonPoints []struct {
   553→		ID               string `json:"id"`
   554→		Message          string `json:"message"`
   555→		MetadataDir      string `json:"metadata_dir"`
   556→		Date             string `json:"date"`
   557→		IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
   558→		ToolUseID        string `json:"tool_use_id"`
   559→		IsLogsOnly       bool   `json:"is_logs_only"`
   560→		CondensationID   string `json:"condensation_id"`
   561→	}
   562→
   563→	if err := json.Unmarshal(output, &jsonPoints); err != nil {
   564→		env.T.Fatalf("failed to parse rewind points: %v\nOutput: %s", err, output)
   565→	}
   566→
   567→	points := make([]RewindPoint, len(jsonPoints))
   568→	for i, jp := range jsonPoints {
   569→		date, _ := time.Parse(time.RFC3339, jp.Date)
   570→		points[i] = RewindPoint{
   571→			ID:               jp.ID,
   572→			Message:          jp.Message,
   573→			MetadataDir:      jp.MetadataDir,
   574→			Date:             date,
   575→			IsTaskCheckpoint: jp.IsTaskCheckpoint,
   576→			ToolUseID:        jp.ToolUseID,
   577→			IsLogsOnly:       jp.IsLogsOnly,
   578→			CondensationID:   jp.CondensationID,
   579→		}
