// Package integration provides test helpers for integration tests.
//
// This file contains helpers for testing interactive CLI prompts using
// pseudo-terminals (pty). These helpers allow tests to simulate user input
// to interactive prompts without requiring actual terminal input.
//
// IMPORTANT: Interactive prompts require ACCESSIBLE=1 environment variable.
// The huh library (used for forms/prompts) normally opens /dev/tty directly
// for input, bypassing stdin. With ACCESSIBLE=1, huh uses accessible mode
// which reads from stdin instead, allowing our pty to provide input.
package integration

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/creack/pty"
)

// RunCommandInteractive executes a CLI command with a pty, allowing interactive
// prompt responses. The respond function receives the pty for reading output
// and writing input. Timeouts and cleanup are managed centrally.
//
// IMPORTANT: This function sets ACCESSIBLE=1 so that huh reads from stdin (the pty)
// instead of opening /dev/tty directly. Without this, user input cannot be simulated.
//
// The respond function should:
//   - Read from ptyFile to detect when prompts appear
//   - Write to ptyFile to send user input (e.g., "y\n" for yes)
//   - Return the output it read (will be combined with remaining output)
//
// Example:
//
//	output, err := env.RunCommandInteractive([]string{"resume", "my-branch"}, func(pty *os.File) string {
//	    out, _ := WaitForPromptAndRespond(pty, "[y/N]", "y\n", 5*time.Second)
//	    return out
//	})
func (env *TestEnv) RunCommandInteractive(args []string, respond func(ptyFile *os.File) string) (string, error) {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), args...)
	cmd.Dir = env.RepoDir
	cmd.Env = append(os.Environ(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		"TERM=xterm",
		"ACCESSIBLE=1", // Required: makes huh read from stdin instead of /dev/tty
	)

	// Start command with a pty
	ptmx, err := pty.Start(cmd)
	if err != nil {
		return "", fmt.Errorf("failed to start pty: %w", err)
	}
	defer ptmx.Close()

	// Let the respond function interact with the pty and collect output
	var respondOutput string
	respondDone := make(chan struct{})
	go func() {
		defer close(respondDone)
		respondOutput = respond(ptmx)
	}()

	// Wait for respond function with timeout
	select {
	case <-respondDone:
		// respond completed
	case <-time.After(10 * time.Second):
		env.T.Log("Warning: respond function timed out")
	}

	// Collect any remaining output after respond is done
	var remaining bytes.Buffer
	remainingDone := make(chan struct{})
	go func() {
		defer close(remainingDone)
		_, _ = io.Copy(&remaining, ptmx)
	}()

	// Wait for process to complete with timeout
	cmdDone := make(chan error, 1)
	go func() {
		cmdDone <- cmd.Wait()
	}()

	var cmdErr error
	select {
	case cmdErr = <-cmdDone:
		// process completed
	case <-time.After(10 * time.Second):
		_ = cmd.Process.Kill()
		cmdErr = fmt.Errorf("process timed out")
	}

	// Give remaining output goroutine time to finish after process exits
	select {
	case <-remainingDone:
	case <-time.After(1 * time.Second):
	}

	return respondOutput + remaining.String(), cmdErr
}

// WaitForPromptAndRespond reads from the pty until it sees the expected prompt text,
// then writes the response. Returns the output read so far.
//
// This is useful for responding to interactive prompts like "[y/N]" confirmations.
// The function reads in a loop with short timeouts until either:
//   - The prompt substring is found (response is sent, returns success)
//   - The overall timeout is reached (returns error)
//   - A non-timeout read error occurs (returns error)
//
// Example:
//
//	out, err := WaitForPromptAndRespond(pty, "[y/N]", "y\n", 5*time.Second)
func WaitForPromptAndRespond(ptyFile *os.File, promptSubstring, response string, timeout time.Duration) (string, error) {
	var output bytes.Buffer
	buf := make([]byte, 1024)
	deadline := time.Now().Add(timeout)

	for time.Now().Before(deadline) {
		// Set read deadline to avoid blocking forever
		_ = ptyFile.SetReadDeadline(time.Now().Add(100 * time.Millisecond))
		n, err := ptyFile.Read(buf)
		if n > 0 {
			output.Write(buf[:n])
			if strings.Contains(output.String(), promptSubstring) {
				// Found the prompt, send response
				_, _ = ptyFile.WriteString(response)
				return output.String(), nil
			}
		}
		if err != nil && !os.IsTimeout(err) {
			return output.String(), err
		}
	}
	return output.String(), fmt.Errorf("timeout waiting for prompt containing %q", promptSubstring)
}

